INSERT INTO public.erp_ajuda_campo (chave, rota, grupo, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum, ordem, status)
VALUES
 ('atendimento.visao','/dashboard/atendimento','Fila de Atendimento','Visão da fila','Escolha onde o chamado caiu: "Meus chamados" (os da sua carteira), "Todos" (toda a equipe) ou "Sem dono" (empresa sem responsável definido).','A carteira define para onde o chamado cai — não quem pode atender; toda a equipe enxerga "Todos".','Meus chamados','Achar que "Meus chamados" esconde o resto — use "Todos" para a fila inteira e "Sem dono" para o que ninguém assumiu.',10,'publicado'),
 ('atendimento.abas','/dashboard/atendimento','Fila de Atendimento','Estado do chamado','Alterna o estado na fila: "⏳ Precisa de mim" (tem resposta esperando aprovação), "🔵 Em curso" (em atendimento), "📤 Aguardando o autor" (resposta enviada, sem confirmação) e "✓ Concluídas".','Separa o que exige ação sua agora do que já foi entregue — chamado entregue não polui a fila aberta.','⏳ Precisa de mim','Procurar um chamado já entregue na aba errada — a busca por número/título varre todas as abas.',20,'publicado'),
 ('atendimento.busca','/dashboard/atendimento','Fila de Atendimento','Buscar chamado','Digite o número do chamado (ex.: 14 ou #14) ou um trecho do título/descrição.','Encontra um chamado específico varrendo TODAS as abas e visões, mesmo os já concluídos.','#14','Esperar que a busca respeite a aba atual — ela ignora a aba de propósito, para você achar o chamado onde quer que esteja.',30,'publicado'),
 ('atendimento.filtro_empresa','/dashboard/atendimento','Fila de Atendimento','Empresa','Selecione uma empresa para ver só os chamados dela.','Foca a fila numa empresa quando você está trabalhando a carteira de um cliente.','todas empresas','Deixar um filtro de empresa ligado e achar que a fila está vazia — volte para "todas empresas".',40,'publicado'),
 ('atendimento.filtro_categoria','/dashboard/atendimento','Fila de Atendimento','Categoria','Filtra por tipo de chamado: bug, melhoria, dúvida ou erro de dado.','Ajuda a priorizar (ex.: resolver bugs antes de melhorias) sem perder o resto de vista.','bug','Confundir "erro de dado" com "bug" — erro de dado é informação errada no cadastro, não falha de código.',50,'publicado'),
 ('atendimento.filtro_responsavel','/dashboard/atendimento','Fila de Atendimento','Responsável','Na visão "Todos", mostra só os chamados de um responsável da equipe.','Permite acompanhar a carga de cada atendente sem sair da fila geral.','todos os responsáveis','Aparece só na visão "Todos" — em "Meus chamados" ele some porque a fila já é a sua.',60,'publicado'),
 ('atendimento.mostrar_demos','/dashboard/atendimento','Fila de Atendimento','Mostrar demos','Marque para incluir os chamados das empresas DEMO (geradas pelo robô de aceitação), ocultos por padrão.','Mantém a fila limpa com os chamados reais no dia a dia e deixa ver os de teste quando precisar.','desmarcado','Deixar marcado e estranhar chamados "de teste" na fila — desmarque para ver só o real.',70,'publicado')
